REPLACE INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (NULL, 'promtail_yml_tmpl', '{\r\n  \"server\": {\r\n    \"http_listen_address\": \"0.0.0.0\",\r\n    \"http_listen_port\": 19080,\r\n	\"grpc_listen_port\": 19081\r\n  },\r\n  \"clients\": [\r\n    {\r\n		<#list clientsMapList as clientMap>\r\n		\"url\" : \"${clientMap.url}\",\r\n		\"bearer_token\": \"${clientMap.token}\"\r\n	  	<#sep>,</#sep>\r\n		</#list>\r\n    }\r\n  ],\r\n  \"positions\": {\r\n    \"filename\": \"/tmp/positions.yaml\"\r\n  },\r\n  \"scrape_configs\": [\r\n  		<#list endpointList as endpoint>\r\n			{\r\n			\"job_name\": \"${endpoint.id?c}_${endpoint_index}\",\r\n			\"pipeline_stages\": [\r\n					<#if endpoint.config.pipeline??&&(endpoint.config.pipeline?size>0)>\r\n						<#list endpoint.config.pipeline as pipeline>\r\n						{\r\n						    <#if pipeline.type  == \"regex\">\r\n							\"regex\": {\r\n								\"expression\": \"${pipeline.expression}\",\r\n								\"source\": \"${pipeline.source}\"\r\n							}\r\n							</#if>\r\n							<#if pipeline.type  == \"json\">\r\n							\"json\": {\r\n							    \"expressions\": {\r\n									<#if pipeline.expressions??&& (pipeline.expressions?size >0)>\r\n									<#list pipeline.expressions?keys as key>\r\n										\"${key}\":\"${pipeline.expressions[key]}\"\r\n										<#sep>,</#sep>\r\n									</#list>\r\n								</#if>\r\n								},\r\n								\"source\": \"${pipeline.source}\"\r\n							}\r\n							</#if>\r\n							<#if pipeline.type  == \"template\">\r\n							 \"template\": {\r\n								\"source\": \"${pipeline.source}\",\r\n								\"template\": \"${pipeline.template}\"\r\n							}\r\n							</#if>\r\n							<#if pipeline.type  == \"timestamp\">\r\n							\"timestamp\": {\r\n								\"source\": \"${pipeline.source}\",\r\n								\"format\": \"${pipeline.format}\"\r\n							}\r\n                            </#if>\r\n							<#if pipeline.type  == \"labels\">	\r\n							\"labels\": {							\r\n								<#if pipeline.labels??&& (pipeline.labels?size >0)>\r\n									<#list pipeline.labels?keys as key>\r\n										\"${key}\":\"${pipeline.labels[key]}\"\r\n										<#sep>,</#sep>\r\n									</#list>\r\n								</#if>\r\n							}\r\n                            </#if>		\r\n							<#if pipeline.type  == \"output\">	\r\n							\"output\": {\r\n								\"source\": \"${pipeline.source}\"\r\n							}\r\n                            </#if>									\r\n						}\r\n						<#sep>,</#sep>\r\n						</#list>\r\n					</#if>\r\n			],\r\n			<#if endpoint.config.type  == \"file\">\r\n				\"static_configs\": [\r\n				{\r\n					\"labels\": {\r\n						\"__path__\": \"${endpoint.config.fileName}\",\r\n						\"datacenter\": 	\"${endpoint.dc.name}\",\r\n						\r\n						\"project\": 		\"${endpoint.project.name}\",\r\n						\r\n						\"asset\": 		\"${endpoint.asset.name}\",\r\n						\r\n						\"module\": 		\"${endpoint.module.name}\",\r\n						\r\n						\"endpoint\":     \"${endpoint.name}\",\r\n						\r\n						<#if endpoint.asset.parent??&&(endpoint.asset.parent?size >0)>\r\n							\"parent_asset\"      :  \"${endpoint.asset.parent.name}\"\r\n						</#if>\r\n						\r\n						<#if endpoint.config.labels??&& (endpoint.config.labels?size >0)>\r\n							,\r\n						</#if>\r\n						<#-- 补充用户自定义 Labels -->\r\n						<#if endpoint.config.labels??&& (endpoint.config.labels?size >0)>\r\n							<#list endpoint.config.labels?keys as key>\r\n								<#if key != \"datacenter\"  && key != \"project\" && key != \"asset\" && key != \"module\" && key != \"endpoint\">\r\n									\"${key}\":\"${endpoint.config.labels[key]}\"<#sep>,</#sep>\r\n								</#if>\r\n							 </#list>\r\n						</#if>\r\n\r\n					}\r\n				}\r\n			  ]\r\n			<#elseif endpoint.config.type == \"syslog\">\r\n				\"syslog\": {\r\n					\"listen_address\": \"${endpoint.config.listenAddress}\",\r\n					\"labels\": {\r\n					   \"datacenter\": 	\"${endpoint.dc.name}\",\r\n						\r\n						\"project\": 		\"${endpoint.project.name}\",\r\n						\r\n						\"asset\": 		\"${endpoint.asset.name}\",\r\n						\r\n						\"module\": 		\"${endpoint.module.name}\",\r\n						\r\n						\"endpoint\":     \"${endpoint.name}\",\r\n						\r\n						<#if endpoint.asset.parent??&&(endpoint.asset.parent?size >0)>\r\n							\"parent_asset\"      :  \"${endpoint.asset.parent.name}\"\r\n						</#if>\r\n						\r\n						<#if endpoint.config.labels??&& (endpoint.config.labels?size >0)>\r\n							,\r\n						</#if>\r\n						<#-- 补充用户自定义 Labels -->\r\n						<#if endpoint.config.labels??&& (endpoint.config.labels?size >0)>\r\n							<#list endpoint.config.labels?keys as key>\r\n								<#if key != \"datacenter\"  && key != \"project\" && key != \"asset\" && key != \"module\" && key != \"endpoint\">\r\n									\"${key}\":\"${endpoint.config.labels[key]}\"<#sep>,</#sep>\r\n								</#if>\r\n							 </#list>\r\n						</#if>\r\n			\r\n					}\r\n				},\r\n				\"relabel_configs\": [\r\n					{\r\n					  \"source_labels\": [\r\n						\"__syslog_message_app_name\"\r\n					  ],\r\n					  \"regex\":\"${endpoint.config.appName}\",\r\n					  \"action\":\"keep\"\r\n					},\r\n					{\r\n					  \"source_labels\": [\r\n						\"__syslog_message_app_name\"\r\n					  ],\r\n					  \"target_label\": \"appName\"\r\n					}\r\n				]	\r\n			<#elseif endpoint.config.type == \"journal\">\r\n				\"journal\": {\r\n					\"labels\": {\r\n						\"datacenter\": 	\"${endpoint.dc.name}\",\r\n						\r\n						\"project\": 		\"${endpoint.project.name}\",\r\n						\r\n						\"asset\": 		\"${endpoint.asset.name}\",\r\n						\r\n						\"module\": 		\"${endpoint.module.name}\",\r\n						\r\n						\"endpoint\":     \"${endpoint.name}\",\r\n						\r\n						<#if endpoint.asset.parent??&&(endpoint.asset.parent?size >0)>\r\n							\"parent_asset\"      :  \"${endpoint.asset.parent.name}\"\r\n						</#if>\r\n						\r\n						<#if endpoint.config.labels??&& (endpoint.config.labels?size >0)>\r\n							,\r\n						</#if>\r\n						<#-- 补充用户自定义 Labels -->\r\n						<#if endpoint.config.labels??&& (endpoint.config.labels?size >0)>\r\n							<#list endpoint.config.labels?keys as key>\r\n								<#if key != \"datacenter\"  && key != \"project\" && key != \"asset\" && key != \"module\" && key != \"endpoint\">\r\n									\"${key}\":\"${endpoint.config.labels[key]}\"<#sep>,</#sep>\r\n								</#if>\r\n							 </#list>\r\n						</#if>\r\n\r\n					}\r\n				},\r\n				\"relabel_configs\": [\r\n					{\r\n					  \"source_labels\": [\r\n						\"__journal__systemd_unit\"\r\n					  ],\r\n					  \"regex\":\"${endpoint.config.unit}\",\r\n					  \"action\":\"keep\"\r\n					},\r\n					{\r\n					  \"source_labels\": [\r\n						\"__journal__systemd_unit\"\r\n					  ],\r\n					  \"target_label\": \"unit\"\r\n					}\r\n				]	\r\n			</#if>\r\n			}\r\n		<#sep>,</#sep>\r\n		</#list>\r\n  ]\r\n}', 1, 'promtail.yml 配置模板');
